mapper.update:
UPDATE job
job_name = #{jobName}, job_desc = #{jobDesc}, requirement = #{requirement}, keywords = #{keywords}, salary = #{salary}, work_address = #{workAddress}, work_experience = #{workExperience}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT id, job_name, job_desc, requirement, keywords, salary, work_address, work_experience, status, create_time, update_time, delivery_count FROM job WHERE hr_id = #{hrId}
AND status = #{status}
AND job_name LIKE CONCAT('%', #{jobName}, '%')
ORDER BY create_time DESC, id DESC
